@app.cell
def _(subprocess, time):
    # ───────────── subprocess helper: one MLC 2024 command, output to a log file, tail returned ─────────────
    def run_mlc(cmd_, env_file_, log_path_, timeout_s_=3600):
        """Runs `cmd_` after sourcing the MLC 2024 environment; returns (returncode, last 30 log lines, seconds)."""
        t0_ = time.time()
        with open(log_path_, "w") as f_:
            r_ = subprocess.run(["bash", "-c", f"source '{env_file_}' && {cmd_}"], stdout=f_, stderr=subprocess.STDOUT,
                                timeout=timeout_s_)
        tail_ = open(log_path_).read().splitlines()[-30:]
        return r_.returncode, tail_, round(time.time() - t0_, 1)
    return (run_mlc,)


@app.cell
def _(HF_TOKEN, MODEL_REPO, WORK_DIR, mo, stages, wc):
    # ───────────── stage: download the merged model (root files only) ─────────────
    MERGED = WORK_DIR / "merged"
    _need = ["config.json", "model.safetensors", "tokenizer.json", "tokenizer_config.json", "generation_config.json"]
    if stages.should_run("phone-download") or not all((MERGED / f).exists() for f in _need):
        from huggingface_hub import hf_hub_download as _dl, list_repo_files as _ls
        _files = [f for f in _ls(MODEL_REPO, token=HF_TOKEN) if "/" not in f and f != ".gitattributes"]
        for _f in mo.status.progress_bar(_files, title=f"Downloading {MODEL_REPO} (root files)"):
            _dl(MODEL_REPO, _f, local_dir=str(MERGED), token=HF_TOKEN)
        assert all((MERGED / f).exists() for f in _need), f"merged model incomplete in {MODEL_REPO}: {_files}"
        stages.mark_done("phone-download", {"files": _files, "repo": MODEL_REPO})
    print(f"[download] merged model in {MERGED}: {sorted(p.name for p in MERGED.iterdir())}")
    return (MERGED,)


@app.cell
def _(CONV_TEMPLATE, LIMITS, MERGED, MLC_ENV, OUT_DIR, QUANT, WORK_DIR, hashlib, json, run_mlc, shutil, stages):
    # ───────────── stage: convert (MLC 2024 convert_weight + gen_config, the app's limits and chat template) ─────────────
    # transformers >= 5 saves Llama's RoPE settings as "rope_parameters" (with rope_theta inside); MLC 2024 reads only the old
    # "rope_scaling" + "rope_theta" and silently falls back to no scaling (caught by the verify stage on the first run).
    # Give MLC a copy of config.json in the old format; the weight files are linked, not copied.
    MLC_INPUT = WORK_DIR / "merged_for_mlc"
    if MLC_INPUT.exists():
        shutil.rmtree(MLC_INPUT)
    MLC_INPUT.mkdir(parents=True)
    for _f in MERGED.iterdir():
        if _f.is_file() and _f.name != "config.json":
            (MLC_INPUT / _f.name).symlink_to(_f.resolve())
    _cfg = json.loads((MERGED / "config.json").read_text())
    _rp = _cfg.pop("rope_parameters", None)
    if _rp is not None:
        _cfg.setdefault("rope_theta", _rp["rope_theta"])
        _cfg.setdefault("rope_scaling", {k_: v_ for k_, v_ in _rp.items() if k_ != "rope_theta"})
    _cfg.setdefault("torch_dtype", _cfg.get("dtype", "bfloat16"))
    # the restored values must be Meta's original Llama-3.2-1B-Instruct settings
    assert _cfg["rope_theta"] == 500000.0, _cfg.get("rope_theta")
    assert _cfg["rope_scaling"] == {"factor": 32.0, "high_freq_factor": 4.0, "low_freq_factor": 1.0,
                                    "original_max_position_embeddings": 8192, "rope_type": "llama3"}, _cfg.get("rope_scaling")
    (MLC_INPUT / "config.json").write_text(json.dumps(_cfg, indent=2))
    print(f"[convert] MLC input: config.json in the old format (rope_theta {_cfg['rope_theta']}, rope_scaling {_cfg['rope_scaling']['rope_type']})")

    # invalidation: convert again whenever the inputs differ from the ones the existing output was made from
    _fp = hashlib.md5(((MLC_INPUT / "config.json").read_text() + QUANT + CONV_TEMPLATE + json.dumps(LIMITS, sort_keys=True)
                       + str((MERGED / "model.safetensors").stat().st_size)).encode()).hexdigest()
    _m = stages.marker("phone-convert") or {}
    _done = (OUT_DIR / "ndarray-cache.json").exists() and (OUT_DIR / "mlc-chat-config.json").exists()
    _stale = bool(_m) and _m.get("input_fingerprint") != _fp
    if _stale:
        print(f"[convert] inputs changed since the last conversion ({_m.get('input_fingerprint')} -> {_fp}): converting again")
    if _stale or stages.should_run("phone-convert") or not _done:
        if OUT_DIR.exists():
            shutil.rmtree(OUT_DIR)
        _rc, _tail, _sec = run_mlc(f"python -m mlc_llm convert_weight '{MLC_INPUT}' --quantization {QUANT} --device cpu -o '{OUT_DIR}'",
                                   MLC_ENV, WORK_DIR / "convert_weight.log")
        print(f"[convert] convert_weight rc {_rc} in {_sec} s")
        assert _rc == 0, "\n".join(_tail)
        _rc, _tail, _sec = run_mlc(f"python -m mlc_llm gen_config '{MLC_INPUT}' --quantization {QUANT} --conv-template {CONV_TEMPLATE} "
                                   f"--context-window-size {LIMITS['context_window_size']} --prefill-chunk-size {LIMITS['prefill_chunk_size']} "
                                   f"--max-batch-size {LIMITS['max_batch_size']} -o '{OUT_DIR}'", MLC_ENV, WORK_DIR / "gen_config.log")
        print(f"[convert] gen_config rc {_rc} in {_sec} s")
        assert _rc == 0, "\n".join(_tail)
        stages.mark_done("phone-convert", {"quantization": QUANT, "conv_template": CONV_TEMPLATE, "limits": LIMITS,
                                           "input_fingerprint": _fp, "rope_restored_from_rope_parameters": _rp is not None})
    print(f"[convert] {OUT_DIR}: {len(list(OUT_DIR.glob('params_shard_*.bin')))} weight shards, "
          f"{sum(p.stat().st_size for p in OUT_DIR.iterdir()) / 1e6:.0f} MB")
    return


@app.cell
def _(CONV_TEMPLATE, LIMITS, OUT_DIR, PHONE_ID, PHONE_LIB, QUANT, REFERENCE_DIR, RUN_NAME, WORK_DIR, hashlib, json, shutil, stages, wc):
    # ───────────── stage: verify against the stock Llama-1B phone model (same tensors and settings -> same GPU code) ─────────────
    def _sha(p_):
        h_ = hashlib.sha256()
        with open(p_, "rb") as f_:
            for b_ in iter(lambda: f_.read(1 << 20), b""):
                h_.update(b_)
        return h_.hexdigest()

    _new_cache = json.loads((OUT_DIR / "ndarray-cache.json").read_text())
    _ref_cache = json.loads((REFERENCE_DIR / "ndarray-cache.json").read_text())
    _sig = lambda c_: sorted((r_["name"], tuple(r_["shape"]), r_["dtype"]) for rec_ in c_["records"] for r_ in rec_["records"])  # noqa: E731
    _new_sig, _ref_sig = _sig(_new_cache), _sig(_ref_cache)
    _diff = sorted(set(_new_sig) ^ set(_ref_sig))
    assert not _diff, f"tensor layout differs from the stock phone model: {_diff[:5]}"
    _new_cfg = json.loads((OUT_DIR / "mlc-chat-config.json").read_text())
    _ref_cfg = json.loads((REFERENCE_DIR / "mlc-chat-config.json").read_text())
    for _k in ("hidden_size", "intermediate_size", "num_attention_heads", "num_hidden_layers", "num_key_value_heads", "vocab_size",
               "head_dim", "tie_word_embeddings", "rope_scaling", "position_embedding_base"):
        assert _new_cfg["model_config"].get(_k) == _ref_cfg["model_config"].get(_k), (_k, _new_cfg["model_config"].get(_k), _ref_cfg["model_config"].get(_k))
    assert _new_cfg["quantization"] == QUANT == _ref_cfg["quantization"]
    assert _new_cfg["conv_template"]["name"] == CONV_TEMPLATE
    assert _new_cfg["conv_template"]["stop_token_ids"] == [128001, 128008, 128009]
    for _k, _v in LIMITS.items():  # MLC 2024 keeps all limits in model_config (context and chunk also at the top level)
        assert _new_cfg["model_config"][_k] == _v, (_k, _new_cfg["model_config"][_k], _v)
        assert _new_cfg.get(_k, _v) == _v, (_k, _new_cfg.get(_k), _v)
    # Tokenizer: transformers 5 saves BPE merges as pairs (["a", "b"]); the engine's 2024 tokenizer only reads strings ("a b") and the app
    # crashed with a Rust panic while loading (phone run 8). Fine-tuning never changes the tokenizer: prove the content is identical
    # to the stock model's, then ship the stock files.
    _ta = json.loads((REFERENCE_DIR / "tokenizer.json").read_text())
    _tb = json.loads((OUT_DIR / "tokenizer.json").read_text())
    assert _ta["model"]["vocab"] == _tb["model"]["vocab"], "tokenizer vocabulary differs from the stock model"
    assert _ta["model"]["merges"] == [" ".join(m_) if isinstance(m_, list) else m_ for m_ in _tb["model"]["merges"]], "merges differ"
    assert [(t_["id"], t_["content"]) for t_ in _ta["added_tokens"]] == [(t_["id"], t_["content"]) for t_ in _tb["added_tokens"]], "special tokens differ"
    for _k in ("normalizer", "pre_tokenizer", "post_processor", "decoder"):
        assert _ta[_k] == _tb[_k], f"tokenizer {_k} differs"
    for _f in ("tokenizer.json", "tokenizer_config.json"):
        shutil.copyfile(REFERENCE_DIR / _f, OUT_DIR / _f)
    assert _new_cfg["tokenizer_files"] == _ref_cfg["tokenizer_files"] and _new_cfg["tokenizer_info"] == _ref_cfg["tokenizer_info"]
    print(f"[verify] tokenizer identical in content to the stock model ({len(_ta['model']['vocab'])} tokens, {len(_ta['model']['merges'])} merges, "
          f"{len(_ta['added_tokens'])} special); stock tokenizer files shipped (format the phone engine reads)")
    # the shards are the fine-tuned weights, not a copy of the stock model
    _same = [f for f in ("params_shard_1.bin", "params_shard_5.bin") if (REFERENCE_DIR / f).exists() and _sha(OUT_DIR / f) == _sha(REFERENCE_DIR / f)]
    assert not _same, f"weights identical to the stock model: {_same}"
    SUMS = {p_.name: _sha(p_) for p_ in sorted(OUT_DIR.iterdir()) if p_.is_file() and p_.name != "SHA256SUMS"}
    (OUT_DIR / "SHA256SUMS").write_text("".join(f"{h_}  {n_}\n" for n_, h_ in SUMS.items()))
    EXPORT_INFO = {"train_run": RUN_NAME, "phone_id": PHONE_ID, "library": PHONE_LIB, "quantization": QUANT, "conv_template": CONV_TEMPLATE,
                   "limits": LIMITS, "n_tensors": len(_new_sig), "n_shards": len(_new_cache["records"]),
                   "size_mb": round(sum(p_.stat().st_size for p_ in OUT_DIR.iterdir()) / 1e6, 1), "sha256": SUMS,
                   "matches_stock_layout": True, "reference": str(REFERENCE_DIR.name), "tokenizer": "stock files (content verified identical)",
                   "content_fingerprint": hashlib.md5(json.dumps(SUMS, sort_keys=True).encode()).hexdigest()}
    wc.put_json(EXPORT_INFO, f"{wc.run_dir(RUN_NAME)}/phone_export.json", WORK_DIR, f"{RUN_NAME}: phone export", None)
    stages.mark_done("phone-verify", {k_: v_ for k_, v_ in EXPORT_INFO.items() if k_ != "sha256"})
    print(f"[verify] OK: {len(_new_sig)} tensors with the stock model's names/shapes/dtypes, same dimensions, {QUANT}, {CONV_TEMPLATE}, "
          f"limits {LIMITS}; weights differ from the stock model; {EXPORT_INFO['size_mb']} MB -> library {PHONE_LIB} fits, no engine rebuild")
    return (EXPORT_INFO,)


@app.cell
def _(EXPORT_INFO, HF_TOKEN, MODEL_REPO, OUT_DIR, QUANT, RUN_NAME, stages, wc):
    # ───────────── stage: upload the phone weights to the model repo (mlc-q4f16_0/) ─────────────
    _mu = stages.marker("phone-upload") or {}
    _changed_u = bool(_mu) and _mu.get("content_fingerprint") != EXPORT_INFO["content_fingerprint"]
    if _changed_u:
        print("[upload] phone files changed since the last upload: uploading again")
    if EXPORT_INFO and (_changed_u or stages.should_run("phone-upload")):
        wc.hf_model_upload_folder(OUT_DIR, MODEL_REPO, f"mlc-{QUANT}", f"{RUN_NAME}: phone weights ({QUANT}, MLC 2024)", HF_TOKEN,
                                  delete_patterns=[f"mlc-{QUANT}/*"])
        stages.mark_done("phone-upload", {"path": f"{MODEL_REPO}/mlc-{QUANT}", "content_fingerprint": EXPORT_INFO["content_fingerprint"]})
        print(f"[upload] -> {MODEL_REPO}/mlc-{QUANT}")
    return


@app.cell
def _(ADB, APP_FILES, EXPORT_INFO, OUT_DIR, PHONE_ID, stages, subprocess):
    # ───────────── stage: push to the phone (only if it is connected, authorised and the app's folder exists) ─────────────
    def _adb(*a_, timeout_=600):
        return subprocess.run([str(ADB), *a_], capture_output=True, text=True, timeout=timeout_)

    PUSHED = False
    _mp = stages.marker("phone-push") or {}
    _changed_p = bool(_mp) and _mp.get("content_fingerprint") != EXPORT_INFO["content_fingerprint"]
    if _changed_p:
        print("[push] phone files changed since the last push: pushing again")
    if EXPORT_INFO and (_changed_p or stages.should_run("phone-push")):
        _dev = _adb("devices").stdout
        if "\tdevice" not in _dev:
            print(f"[push] SKIPPED: phone not connected or not authorised ({_dev.strip().splitlines()[-1] if _dev.strip() else 'no adb output'}). "
                  "Unlock it, allow USB debugging, re-run this cell")
        elif _adb("shell", "ls", APP_FILES).returncode != 0:
            print(f"[push] SKIPPED: {APP_FILES} does not exist: install the app and open it once, then re-run (pushing now would "
                  "turn the model folder into the app folder)")
        else:
            _tmp = f"/data/local/tmp/{PHONE_ID}"
            _adb("shell", "rm", "-rf", _tmp)
            _r = _adb("push", str(OUT_DIR), "/data/local/tmp/", timeout_=1800)
            assert _r.returncode == 0, _r.stderr[-500:]
            _r = _adb("shell", f"rm -rf {APP_FILES}/{PHONE_ID} && mv {_tmp} {APP_FILES}/")
            assert _r.returncode == 0, _r.stderr[-500:]
            _n = _adb("shell", f"ls {APP_FILES}/{PHONE_ID} | wc -l").stdout.strip()
            _local_n = len(list(OUT_DIR.iterdir()))
            assert _n == str(_local_n), f"phone has {_n} files, laptop {_local_n}"
            stages.mark_done("phone-push", {"phone_dir": f"{APP_FILES}/{PHONE_ID}", "files": _local_n,
                                            "content_fingerprint": EXPORT_INFO["content_fingerprint"]})
            PUSHED = True
            print(f"[push] OK: {_local_n} files -> {APP_FILES}/{PHONE_ID}")
    return (PUSHED,)


@app.cell
def _(EXPORT_INFO, PHONE_ID, PHONE_LIB, PUSHED):
    # ───────────── summary ─────────────
    print(f"done. Phone model {PHONE_ID} ({EXPORT_INFO['size_mb'] if EXPORT_INFO else '?'} MB) "
          f"{'is on the phone' if PUSHED else 'is NOT on the phone yet (see [push])'}. "
          f"App: add LlmModel(id: '{PHONE_ID}', lib: '{PHONE_LIB}', ...) to LlmService.models, rebuild, install; then test on the Note10 "
          "and log the timings and exercises (RESEARCH_LOG §6.2).")
    return


if __name__ == "__main__":
    app.run()
